77	Status Version::Save(const std::string &path, const Version &version) {
78	  std::ofstream ofs;
79	  ailego::FileHelper::OpenOfstream(ofs, path, std::ios::binary);
80	  if (!ofs.is_open()) {
81	    LOG_ERROR("Failed to open file: %s, err: %s", path.c_str(),
82	              ailego::FileHelper::GetLastErrorString().c_str());
83	    return Status::InternalError("Failed to open file: %s", path.c_str());
84	  }
85	
86	  proto::Manifest manifest;
87	
88	  // set schema
89	  auto schema = ProtoConverter::ToPb(version.schema());
90	  manifest.mutable_schema()->Swap(&schema);
91	
92	  manifest.set_enable_mmap(version.enable_mmap());
93	
94	  // set segments meta
95	  for (auto &meta : version.persisted_segment_metas()) {
96	    auto meta_pb = ProtoConverter::ToPb(*meta);
97	    manifest.add_persisted_segment_metas()->Swap(&meta_pb);
98	  }
99	
100	  if (version.writing_segment_meta()) {
101	    auto meta_pb = ProtoConverter::ToPb(*version.writing_segment_meta());
102	    manifest.mutable_writing_segment_meta()->Swap(&meta_pb);
103	  }
104	
105	  manifest.set_id_map_path_suffix(version.id_map_path_suffix());
106	  manifest.set_delete_snapshot_path_suffix(
107	      version.delete_snapshot_path_suffix());
108	  manifest.set_next_segment_id(version.next_segment_id());
109	
110	  if (!manifest.SerializeToOstream(&ofs)) {
111	    LOG_ERROR("Failed to serialize manifest to file: %s", path.c_str());
112	    return Status::InternalError("Failed to serialize manifest to file");
113	  }
114	
115	  return Status::OK();
116	}
