190	Result<VersionManager::Ptr> VersionManager::Recovery(const std::string &path) {
191	  namespace fs = std::filesystem;
192	  auto u8path = ailego::FileHelper::PathFromUtf8(path);
193	  if (!fs::exists(u8path)) {
194	    LOG_ERROR("VersionManager::Recovery: path %s does not exist", path.c_str());
195	    return tl::make_unexpected(
196	        Status::NotFound("path ", path, " does not exist"));
197	  }
198	  if (!fs::is_directory(u8path)) {
199	    LOG_ERROR("VersionManager::Recovery: path %s is not a directory",
200	              path.c_str());
201	    return tl::make_unexpected(
202	        Status::InvalidArgument("path", path, " is not a directory"));
203	  }
204	
205	  std::string prefix = GetFileName(FileID::MANIFEST_FILE);
206	  std::string manifest_pattern = "^" + prefix + R"(\.(\d+)$)";
207	  std::regex regex(manifest_pattern);
208	  std::smatch match;
209	
210	  uint64_t max_id = UINT64_MAX;
211	  std::string version_path;
212	
213	  for (const auto &entry : fs::directory_iterator(u8path)) {
214	    if (entry.is_regular_file()) {
215	      std::string filename = entry.path().filename().u8string();
216	      if (std::regex_match(filename, match, regex)) {
217	        uint64_t id = std::stoull(match[1].str());
218	        if (id > max_id || max_id == UINT64_MAX) {
219	          max_id = id;
220	          version_path = entry.path().u8string();
221	        }
222	      }
223	    }
224	  }
225	
226	  if (max_id == UINT64_MAX) {
227	    LOG_ERROR("Failed to find the version file in collction_path(%s)",
228	              path.c_str());
229	    return tl::make_unexpected(
230	        Status::NotFound("Failed to find the version file"));
231	  }
232	
233	  Version version;
234	  auto s = Version::Load(version_path, &version);
235	  CHECK_RETURN_STATUS_EXPECTED(s);
236	
237	  VersionManager::Ptr manager =
238	      VersionManager::Ptr(new VersionManager(path, version, max_id + 1));
239	
240	  return manager;
241	}
