282	Status VersionManager::flush() {
283	  std::lock_guard lock(mtx_);
284	
285	  std::string current_path;
286	  if (version_id_ != 0) {
287	    current_path =
288	        FileHelper::MakeFilePath(path_, FileID::MANIFEST_FILE, version_id_ - 1);
289	  }
290	
291	  auto s = Version::Save(
292	      FileHelper::MakeFilePath(path_, FileID::MANIFEST_FILE, version_id_++),
293	      current_version_);
294	  CHECK_RETURN_STATUS(s);
295	
296	  if (!current_path.empty()) {
297	    FileHelper::RemoveFile(current_path);
298	  }
299	
300	  return Status::OK();
301	}
